<template>
  <div class="monitor-page">
    <section class="monitor-head"><div><div class="eyebrow">LIVE AIRSPACE MONITORING</div><h1>航空实时监控</h1><p>实时航迹、告警提醒、扇区负荷与管制指令纠错</p></div><div class="live-chip"><i></i> LIVE <span>{{ lastUpdate }}</span></div></section>

    <section class="monitor-grid">
      <div v-if="auth.has('monitor:track')" class="panel radar-panel"><div class="panel-head"><div><h3>实时雷达航迹</h3><span>RADAR TRACK / {{ radar.total || 0 }} TRACKS / {{ radar.warnCount || 0 }} WARN</span></div><el-select v-model="sector" size="small" style="width:130px" @change="refreshMonitor"><el-option label="全部扇区" value="ALL"/><el-option v-for="s in sectors" :key="s.sectorCode" :label="s.sectorName" :value="s.sectorCode"/></el-select></div><div ref="radarEl" class="radar-chart"></div></div>
      <div v-if="auth.has('monitor:warn')" class="panel warnings-panel"><div class="panel-head"><div><h3>实时告警</h3><span>LIVE WARNINGS / 自动计算</span></div><el-button size="small" @click="refreshMonitor">刷新</el-button></div><div class="warning-list"><div v-for="(w,i) in liveWarnings.list || []" :key="w.warnKey || i" class="warning-item" :class="w.type === 'DANGER' ? 'danger' : 'info'"><div class="warning-badge">{{ w.predicted ? '预警' : w.typeName }}</div><div class="warning-main"><div class="warning-title">{{ (w.flights||[]).join('  ↔  ') }} <span>{{ w.sectorName }}</span></div><div class="warning-text">{{ w.message }}</div><div class="warning-meta">水平 {{ w.horizontalKm ?? '-' }} km · 垂直 {{ w.verticalM ?? '-' }} m <em v-if="w.predicted">· {{ w.predictSeconds }}s 后最近接近</em></div></div><el-button v-if="w.warnId && !w.handled" link type="danger" size="small" @click="handleWarning(w)">处理</el-button></div><el-empty v-if="!(liveWarnings.list||[]).length" description="暂无实时告警" :image-size="60" /></div></div>
    </section>

    <section v-if="auth.hasAny(['monitor:track','monitor:atcCheck'])" class="monitor-grid lower"><div v-if="auth.has('monitor:track')" class="panel"><div class="panel-head"><div><h3>扇区运行概况</h3><span>SECTOR STATUS / 实时</span></div></div><div class="sector-cards"><div v-for="s in (sectorSummary.list || [])" :key="s.sectorCode" class="sector-card"><div class="sector-title"><b>{{ s.sectorCode }}</b><span>{{ s.sectorName }}</span></div><div class="sector-metrics"><div><span>航迹</span><b>{{ s.trackCount }}</b></div><div><span>告警</span><b :class="{dangerText:s.warnCount}">{{ s.warnCount }}</b></div><div><span>负荷</span><b>{{ s.loadRate }}%</b></div><div><span>饱和度</span><b>{{ s.saturation }}%</b></div></div><el-progress :percentage="Math.min(100,s.loadRate||0)" :stroke-width="6" :show-text="false"/><div class="duty">{{ (s.onDuty||[]).map(x=>x.controllerName).join(' / ') || '暂无在岗' }}</div></div></div></div>
      <div v-if="auth.has('monitor:atcCheck')" class="panel instruction-panel"><div class="panel-head"><div><h3>管制指令纠错</h3><span>INSTRUCTION CHECK / ALT · SPD · HDG</span></div></div><el-form :model="form" label-position="top" class="check-form"><div class="form-row"><el-input v-model="form.flightNo" placeholder="输入当前航班号，例如 AAR218"/></div><div class="form-row two"><el-select v-model="form.instructionType"><el-option label="高度 ALT" value="ALT"/><el-option label="速度 SPD" value="SPD"/><el-option label="航向 HDG" value="HDG"/></el-select><el-input-number v-model="form.value" :controls="false" :min="0" :max="100000" style="width:100%"/></div><div class="form-row two"><el-input v-model="form.controller" placeholder="管制员（可选）"/><el-button type="primary" :loading="checking" @click="check">检查指令</el-button></div></el-form><div v-if="checkResult" class="check-result" :class="checkResult.level==='ERROR'?'bad':(checkResult.level==='OK'?'ok':'warn')"><div class="result-line"><b>{{ checkResult.level==='ERROR' ? '✗ 存在冲突，禁止发布' : (checkResult.level==='WARN' ? '⚠ 存在风险项' : '✓ 指令可发布') }}</b><span>{{ levelName[checkResult.level] || checkResult.level }}</span></div><p>{{ checkResult.instructionText }}</p><div v-if="checkResult.issues?.length" class="issues"><div v-for="(issue,i) in checkResult.issues" :key="i" :class="'lv-'+issue.level">{{ issue.message }}</div></div><div class="suggestion">建议：{{ checkResult.suggestion }}</div></div></div></section>

    <section v-if="auth.has('monitor:track')" class="panel flight-table"><div class="panel-head"><div><h3>当前航班</h3><span>LIVE TRACK LIST / 点击查看历史轨迹</span></div><div class="flight-count">{{ radar.total || 0 }} 航班</div></div><el-table :data="radar.list || []" height="290" :row-class-name="rowClass"><el-table-column prop="flightNo" label="航班号" width="120"/><el-table-column prop="companyName" label="航司" width="120"/><el-table-column prop="sectorName" label="扇区" width="140"/><el-table-column prop="statusName" label="状态" width="90"/><el-table-column prop="altitude" label="高度(m)" width="100"/><el-table-column prop="speed" label="速度(km/h)" width="110"/><el-table-column prop="direction" label="航向" width="80"/><el-table-column label="告警"><template #default="scope"><el-tag v-if="scope.row.warn" type="danger" effect="dark">{{ scope.row.warnTypes?.join('/') || '告警' }}</el-tag><span v-else class="safe-label">正常</span></template></el-table-column><el-table-column fixed="right" label="操作" width="88"><template #default="scope"><el-button link type="primary" @click="viewTrack(scope.row.flightNo)">轨迹</el-button></template></el-table-column></el-table></section>

    <el-dialog v-model="trackVisible" title="历史航迹" width="720px" class="track-dialog"><div ref="trackEl" class="track-chart"></div><div v-if="track.current" class="track-info"><span>{{ track.current.flightNo }}</span><span>{{ track.current.companyName }}</span><span>{{ track.current.sectorName }}</span><span>高度 {{ track.current.altitude }}m</span><span>速度 {{ track.current.speed }}km/h</span></div></el-dialog>
  </div>
</template>

<script setup>
import * as echarts from 'echarts'
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { getDutyList, getLiveWarnings, getRadarFlights, getRadarTrack, getSectorList, getSectorSummary, checkInstruction, handleWarn } from '@/api/analysis'
import { useAuthStore } from '@/store'
import message from '@/utils/message'

const auth = useAuthStore()

const sector=ref('ALL'), sectors=ref([]), radar=ref({list:[]}), liveWarnings=ref({list:[]}), sectorSummary=ref({list:[]}), lastUpdate=ref('--'), checking=ref(false), checkResult=ref(null)
const form=reactive({flightNo:'AAR218',instructionType:'ALT',value:9800,controller:''})
// 与后端 level 枚举（OK/INFO/WARN/ERROR）对应
const levelName={OK:'正常',INFO:'提示',WARN:'警告',ERROR:'冲突'}
const radarEl=ref(null),trackEl=ref(null); let radarChart,trackChart,resize,monitorTimer
const trackVisible=ref(false),track=ref({})
const sectorLabel=computed(()=>sector.value==='ALL'?'全部扇区':sector.value)
function radarOption(){ const list=radar.value.list||[]; return {tooltip:{trigger:'item',formatter:p=>{const d=p.data||{};return `<b>${d.flightNo||''}</b><br/>${d.sectorName||''}<br/>高度 ${d.altitude||'-'}m · 速度 ${d.speed||'-'}km/h`}},grid:{left:45,right:20,top:15,bottom:38},xAxis:{type:'value',min:114,max:129,axisLine:{lineStyle:{color:'#2a4962'}},axisLabel:{color:'#7691aa'},splitLine:{lineStyle:{color:'rgba(93,126,155,.13)'}}},yAxis:{type:'value',min:34.8,max:42.8,axisLine:{lineStyle:{color:'#2a4962'}},axisLabel:{color:'#7691aa'},splitLine:{lineStyle:{color:'rgba(93,126,155,.13)'}}},series:[{type:'scatter',symbol:'triangle',symbolSize:12,itemStyle:{shadowBlur:10},
// ECharts 散点图按数据项着色（系列级 color 回调对 scatter 不生效）：告警红 / 预警黄 / 正常蓝
data:list.map(f=>({value:[f.longitude,f.latitude],...f,itemStyle:{color:f.warn?'#ff6475':(f.predictWarn?'#ffc34f':'#58c7ff'),shadowColor:f.warn?'rgba(255,100,117,.55)':(f.predictWarn?'rgba(255,195,79,.5)':'rgba(75,187,255,.38)')}})),
label:{show:true,formatter:p=>p.data.flightNo,color:'#8eb1d1',fontSize:9,position:'right'}},{type:'scatter',symbolSize:5,itemStyle:{color:'#94e9ff'},data:[{value:[114.6485,38.7161]},{value:[128.7592,42.2979]},{value:[114.6485,35.5198]},{value:[128.7592,35.5198]}]}]}}
async function renderRadar(){ await nextTick(); if(!radarEl.value)return; if(!radarChart)radarChart=echarts.init(radarEl.value); radarChart.setOption(radarOption(),true) }
async function refreshMonitor(){
  const p = sector.value === 'ALL' ? {} : { sectorCode: sector.value }
  // 按后端 monitor:track / monitor:warn 权限决定是否发起对应请求（无权限不请求，避免 403）
  const canTrack = auth.has('monitor:track'), canWarn = auth.has('monitor:warn')
  const skip = Promise.resolve(null)
  const [sl, s, w, r] = await Promise.all([
    getSectorList(),
    canTrack ? getSectorSummary(p) : skip,
    canWarn ? getLiveWarnings(p) : skip,
    canTrack ? getRadarFlights(p) : skip
  ])
  sectors.value = sl || []
  if (!canTrack) {
    sectorSummary.value = { list: [] }
  } else if (Array.isArray(s?.list)) {
    sectorSummary.value = s
  } else if (s?.sectorCode) {
    sectorSummary.value = { list: [s], totalTracks: s.trackCount || 0, totalWarns: s.warnCount || 0 }
  } else {
    sectorSummary.value = { list: [] }
  }
  if (w) liveWarnings.value = w
  if (r) radar.value = r
  lastUpdate.value = r?.updateTime || w?.updateTime || '--'
  if (canTrack) renderRadar()
}
async function initial(){ await refreshMonitor() }
async function handleWarning(w){ try{await handleWarn(w.warnTable,w.warnId);message.success('告警已处理');await refreshMonitor()}catch(e){message.error(e.message||'处理失败')} }
async function check(){ if(!form.flightNo||form.value===null){message.warning('请填写航班号和指令数值');return};checking.value=true;try{checkResult.value=await checkInstruction({ ...form, value:Number(form.value), save:false })}catch(e){message.error(e.message||'检查失败')}finally{checking.value=false} }
async function viewTrack(flightNo){track.value=await getRadarTrack({flightNo,points:50});trackVisible.value=true;await nextTick();if(!trackEl.value)return;if(!trackChart)trackChart=echarts.init(trackEl.value);const pts=track.value.points||[];trackChart.setOption({tooltip:{trigger:'item',formatter:p=>p.data.time||''},grid:{left:48,right:20,top:20,bottom:40},xAxis:{type:'value',min:114,max:129,axisLabel:{color:'#7691aa'},splitLine:{lineStyle:{color:'rgba(93,126,155,.13)'}}},yAxis:{type:'value',min:34.8,max:42.8,axisLabel:{color:'#7691aa'},splitLine:{lineStyle:{color:'rgba(93,126,155,.13)'}}},series:[{type:'line',smooth:true,data:pts.map(p=>[p.longitude,p.latitude]),lineStyle:{color:'#53c8ff',width:3},symbol:'circle',symbolSize:5},{type:'effectScatter',data:pts.slice(-1).map(p=>({value:[p.longitude,p.latitude],time:p.time})),symbolSize:12,itemStyle:{color:'#5fe0c1'}}]},true)}
function rowClass({row}){return row.warn?'warn-row':''}
onMounted(()=>{initial();resize=()=>{radarChart?.resize();trackChart?.resize()};window.addEventListener('resize',resize);monitorTimer=setInterval(refreshMonitor,30000)})
onBeforeUnmount(()=>{window.removeEventListener('resize',resize);clearInterval(monitorTimer);radarChart?.dispose();trackChart?.dispose()})
</script>

<style scoped>
.monitor-page{min-height:100vh;padding:22px 26px 32px;background:radial-gradient(circle at 18% 0%,rgba(29,110,167,.16),transparent 28%),#071225}.monitor-head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:16px}.eyebrow{font-size:11px;letter-spacing:3px;color:#4bb8f6}.monitor-head h1{margin:4px 0 0;font-size:28px;color:#e7f4ff}.monitor-head p{margin:5px 0 0;color:#718ca9;font-size:13px}.live-chip{display:flex;gap:10px;align-items:center;padding:9px 13px;border-radius:999px;background:rgba(15,42,61,.72);border:1px solid rgba(77,210,177,.16);color:#56d9b0;font-size:11px}.live-chip i{width:7px;height:7px;border-radius:50%;background:#36dcab;box-shadow:0 0 10px #36dcab}.live-chip span{color:#7993ac;margin-left:2px}.monitor-grid{display:grid;grid-template-columns:1.65fr 1fr;gap:12px;margin-bottom:12px}.monitor-grid.lower{grid-template-columns:1.45fr 1fr}.panel{background:linear-gradient(160deg,rgba(13,31,53,.96),rgba(7,20,37,.96));border:1px solid rgba(106,174,224,.11);border-radius:12px}.radar-panel{padding:14px 16px 10px}.warnings-panel,.instruction-panel,.flight-table{padding:14px 16px}.panel-head{display:flex;align-items:flex-start;justify-content:space-between}.panel-head h3{margin:0;color:#e3f3ff;font-size:15px}.panel-head span{font-size:9px;letter-spacing:1.7px;color:#587694}.radar-chart{height:410px}.warning-list{height:410px;overflow:auto;margin-top:10px}.warning-item{display:flex;gap:10px;padding:12px 6px;border-bottom:1px solid rgba(115,159,195,.08)}.warning-badge{flex:none;width:64px;height:24px;display:grid;place-items:center;font-size:10px;border-radius:6px;background:rgba(255,84,103,.12);color:#ff8090}.warning-item.info .warning-badge{background:rgba(255,194,83,.11);color:#ffca67}.warning-main{flex:1;min-width:0}.warning-title{color:#e6f2ff;font-size:12px;font-weight:600}.warning-title span{float:right;color:#6b89a5;font-weight:400}.warning-text{color:#8fa9c0;font-size:11px;line-height:18px;margin-top:3px}.warning-meta{color:#607a93;font-size:10px;margin-top:3px}.warning-meta em{font-style:normal;color:#ffc15d}.sector-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:12px}.sector-card{padding:12px;border-radius:10px;border:1px solid rgba(107,174,222,.1);background:rgba(13,34,57,.7)}.sector-title{display:flex;gap:8px;align-items:center}.sector-title b{width:28px;height:28px;border-radius:8px;display:grid;place-items:center;background:#123b5c;color:#5ed0ff}.sector-title span{font-size:11px;color:#9bb3c9}.sector-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:13px 0}.sector-metrics div{display:flex;flex-direction:column}.sector-metrics span{font-size:9px;color:#617b95}.sector-metrics b{margin-top:2px;color:#e6f4ff;font-size:13px}.dangerText{color:#ff7180!important}.duty{font-size:10px;color:#6c879f;margin-top:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.check-form{margin-top:14px}.form-row{margin-bottom:10px}.form-row.two{display:grid;grid-template-columns:1fr 1fr;gap:10px}.check-result{padding:12px;border-radius:9px;margin-top:10px;background:rgba(32,70,66,.24);border:1px solid rgba(75,220,175,.14)}.check-result.bad{background:rgba(80,41,47,.24);border-color:rgba(255,104,118,.18)}.check-result.warn{background:rgba(80,63,30,.22);border-color:rgba(255,195,79,.2)}.result-line{display:flex;justify-content:space-between}.result-line b{color:#5ce0b5}.bad .result-line b{color:#ff7b88}.warn .result-line b{color:#ffc34f}.result-line span{font-size:10px;color:#738da7}.check-result p{font-size:11px;color:#d5e8f8}.issues div{font-size:10px;margin:3px 0}.issues .lv-ERROR{color:#ff8894}.issues .lv-WARN{color:#ffc34f}.issues .lv-INFO{color:#8fb2cd}.suggestion{font-size:10px;color:#7fa0ba;border-top:1px solid rgba(110,160,195,.08);padding-top:8px}.flight-table{margin-top:12px}.flight-count{font-size:12px;color:#74cfff}.safe-label{font-size:11px;color:#63cfac}.track-chart{height:420px}.track-info{display:flex;gap:18px;color:#7694af;font-size:11px;margin-top:6px}.track-info span:first-child{color:#e1f1ff;font-weight:700}.flight-table :deep(.el-table){--el-table-bg-color:transparent;--el-table-tr-bg-color:transparent;--el-table-header-bg-color:rgba(22,48,77,.6);--el-table-row-hover-bg-color:rgba(66,141,197,.08);--el-table-text-color:#abc0d2;--el-table-header-text-color:#7f9bb6}.flight-table :deep(.warn-row td){background:rgba(255,74,96,.04)!important}.flight-table :deep(.el-table__inner-wrapper::before){display:none}@media(max-width:1100px){.monitor-grid,.monitor-grid.lower{grid-template-columns:1fr}.sector-cards{grid-template-columns:1fr}.radar-chart{height:330px}.warning-list{height:330px}}
</style>
